// OpenMapTiles poi `subclass` (checked first) or `class` -> Maki icon.
// The tile profile (resources/tilemaker/process-openmaptiles.lua) sets class
// to the OMT class (cafe, lodging, ...) or the OSM key (amenity, shop, ...)
// and subclass to the OSM value; place_of_worship carries the religion in
// subclass. Anything unlisted gets no icon, as before.
var _SZ_POI_ICON = {
  restaurant: 'restaurant', fast_food: 'fast-food', food_court: 'fast-food',
  cafe: 'cafe', bar: 'bar', nightclub: 'bar', pub: 'beer', biergarten: 'beer',
  beer: 'beer', ice_cream: 'ice-cream', bakery: 'bakery',
  grocery: 'grocery', supermarket: 'grocery', convenience: 'shop', shop: 'shop',
  mall: 'shop', clothing_store: 'clothing-store', clothes: 'clothing-store',
  alcohol_shop: 'alcohol-shop',
  lodging: 'lodging', hotel: 'lodging', motel: 'lodging', hostel: 'lodging',
  guest_house: 'lodging', campsite: 'campsite', camp_site: 'campsite',
  caravan_site: 'campsite',
  hospital: 'hospital', clinic: 'doctor', doctors: 'doctor', dentist: 'dentist',
  pharmacy: 'pharmacy',
  school: 'school', kindergarten: 'school', college: 'college',
  university: 'college', library: 'library',
  museum: 'museum', art_gallery: 'art-gallery', gallery: 'art-gallery',
  artwork: 'art-gallery', attraction: 'attraction', viewpoint: 'viewpoint',
  monument: 'monument', memorial: 'monument', castle: 'castle', ruins: 'castle',
  zoo: 'zoo', aquarium: 'aquarium', theatre: 'theatre', cinema: 'cinema',
  music: 'music', information: 'information', picnic_site: 'picnic-site',
  stadium: 'stadium', swimming: 'swimming', swimming_pool: 'swimming',
  golf: 'golf', park: 'park', garden: 'garden', playground: 'playground',
  bus: 'bus', railway: 'rail', station: 'rail', halt: 'rail',
  tram_stop: 'rail-light', subway: 'rail-metro', entrance: 'entrance',
  aerodrome: 'airport', fuel: 'fuel', parking: 'parking', car: 'car',
  bicycle: 'bicycle', bicycle_rental: 'bicycle', harbor: 'harbor',
  ferry_terminal: 'ferry',
  bank: 'bank', atm: 'bank', post: 'post', police: 'police',
  fire_station: 'fire-station', town_hall: 'town-hall',
  place_of_worship: 'place-of-worship', christian: 'religious-christian',
  jewish: 'religious-jewish', muslim: 'religious-muslim',
  buddhist: 'religious-buddhist',
  toilets: 'toilet', drinking_water: 'drinking-water', cemetery: 'cemetery',
  laundry: 'laundry', hairdresser: 'hairdresser'
};

// Disc colour per group, so a glance separates food from health from
// transport. White glyph on a mid-tone disc reads on both map themes.
var _SZ_POI_GROUP_COLOR = {
  food: '#d9730d', shop: '#8e5cc6', lodging: '#2e7fb8', health: '#d23f3f',
  education: '#946434', culture: '#b8437a', leisure: '#3a8f46',
  transport: '#3a6ea5', civic: '#66707b'
};
var _SZ_POI_GROUP = {
  food: ['restaurant', 'fast-food', 'cafe', 'bar', 'beer', 'ice-cream', 'bakery'],
  shop: ['grocery', 'shop', 'clothing-store', 'alcohol-shop', 'hairdresser', 'laundry'],
  lodging: ['lodging', 'campsite'],
  health: ['hospital', 'doctor', 'dentist', 'pharmacy'],
  education: ['school', 'college', 'library'],
  culture: ['museum', 'art-gallery', 'attraction', 'viewpoint', 'monument', 'castle',
            'zoo', 'aquarium', 'theatre', 'cinema', 'music', 'information'],
  leisure: ['stadium', 'swimming', 'golf', 'park', 'garden', 'playground', 'picnic-site'],
  transport: ['bus', 'rail', 'rail-light', 'rail-metro', 'entrance', 'airport', 'fuel',
              'parking', 'car', 'bicycle', 'harbor', 'ferry'],
  civic: ['bank', 'post', 'police', 'fire-station', 'town-hall', 'place-of-worship',
          'religious-christian', 'religious-jewish', 'religious-muslim',
          'religious-buddhist', 'toilet', 'drinking-water', 'cemetery']
};
var _SZ_POI_IMAGE_PREFIX = 'sz-poi-';

// icon-image for the poi-label layer: subclass first, then class, else ''
// (no icon). One `match` per key keeps it a plain lookup in the worker.
function _szPoiIconExpr() {
  function lookup(prop, fallback) {
    var m = ['match', ['get', prop]];
    Object.keys(_SZ_POI_ICON).forEach(function(k) {
      m.push(k, _SZ_POI_IMAGE_PREFIX + _SZ_POI_ICON[k]);
    });
    m.push(fallback);
    return m;
  }
  return lookup('subclass', lookup('class', ''));
}

function _szPoiIconColor(icon) {
  for (var g in _SZ_POI_GROUP) {
    if (_SZ_POI_GROUP[g].indexOf(icon) >= 0) return _SZ_POI_GROUP_COLOR[g];
  }
  return _SZ_POI_GROUP_COLOR.civic;
}

// Draw one icon: a 17px disc with a white ring and the 15-unit Maki glyph
// scaled into it, at the device pixel ratio (capped at 2: at 3x each icon
// would be 2.25x the memory for no visible gain at this size). Returns
// {image: ImageData, pixelRatio} for map.addImage, or null when this browser cannot
// draw SVG path strings (Path2D) -- the POI then shows its label alone.
function _szRenderPoiIcon(icon, ratio) {
  var d = _SZ_MAKI[icon];
  if (!d || typeof Path2D === 'undefined') return null;
  var r = Math.max(1, Math.min(2, Math.round(ratio || 1)));
  var size = 17 * r;
  try {
    var canvas = document.createElement('canvas');
    canvas.width = canvas.height = size;
    var ctx = canvas.getContext('2d');
    if (!ctx) return null;
    ctx.beginPath();
    ctx.arc(size / 2, size / 2, size / 2 - 0.5 * r, 0, Math.PI * 2);
    ctx.fillStyle = _szPoiIconColor(icon);
    ctx.fill();
    ctx.lineWidth = r;
    ctx.strokeStyle = 'rgba(255,255,255,0.9)';
    ctx.stroke();
    var glyph = 11 * r;                         // 15-unit glyph in 11 CSS px
    ctx.translate((size - glyph) / 2, (size - glyph) / 2);
    ctx.scale(glyph / 15, glyph / 15);
    ctx.fillStyle = '#fff';
    ctx.fill(new Path2D(d));
    return { image: ctx.getImageData(0, 0, size, size), pixelRatio: r };
  } catch (e) {
    return null;
  }
}

function initPoiIcons(map) {
  var failed = {};
  map.on('styleimagemissing', function(e) {
    var id = e && e.id;
    if (!id || id.indexOf(_SZ_POI_IMAGE_PREFIX) !== 0 || failed[id]) return;
    if (map.hasImage(id)) return;
    var icon = _szRenderPoiIcon(id.slice(_SZ_POI_IMAGE_PREFIX.length), window.devicePixelRatio);
    if (!icon) { failed[id] = true; return; }
    try {
      map.addImage(id, icon.image, { pixelRatio: icon.pixelRatio });
    } catch (err) {
      failed[id] = true;
      dbg('poi icon failed', id, describeError(err));
    }
  });
}
